#!/usr/bin/env python3
"""Generate pinned supporting-skill instructions from the reviewed inventory."""

import argparse
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
INVENTORY = ROOT / "scripts/supporting-skills.json"
OUTPUT = ROOT / "Student/rebuild/supporting-skills.md"


def render(inventory):
    lines = [
        "# Supporting skills",
        "",
        "[Setup and usage](setup.md) | [First challenge](Challenge-00.md)",
        "",
        "<!-- Generated by scripts/supporting-skills.py; edit the inventory, not this file. -->",
        "",
        "Install in your **application repository**, not this tooling repository.",
        f"Requires Git, npx, and Node.js **{inventory['minimumNode']} or newer**.",
        "These project-local copies are separate from the Agentic Modernization plugin.",
        "`cloud-architecture-diagram` is already bundled in the plugin; do not install a second copy.",
        "Review existing skills first: installation can overwrite selected copies.",
        "Stop on errors and inspect partial skill files and `skills-lock.json` before retrying.",
        "",
        f"Sources and paths verified on {inventory['verifiedOn']}; commands pin source",
        "commits and the installer version. Review upstream licenses and skill behavior.",
        "Pins make installation reproducible, not a claim of completed behavioral evaluation.",
        "Review and commit skill copies/lockfiles only according to your repository policy.",
        "",
        "Use `/skills` in Copilot CLI or **Chat: Configure Skills** in VS Code to",
        "verify discovery. Reload the host if needed. Select the name shown by your",
        "host rather than guessing a plugin prefix. Do not install duplicate global",
        "and workspace copies of the same skill without reviewing precedence.",
        "",
    ]
    for profile in inventory["profiles"]:
        lines.extend([f"## {profile['title']}", "", profile["when"], ""])
        for source in profile["sources"]:
            url = (
                f"https://github.com/{source['repository']}/tree/"
                f"{source['revision']}/{source['path']}"
            )
            lines.extend([f"Source: [{source['repository']}]({url}).", ""])
            lines.extend(
                f"- **`{name}`**: {description}"
                for name, description in source["skills"].items()
            )
            names = " ".join(source["skills"])
            lines.extend([
                "",
                "```bash",
                f"npx --yes {inventory['installer']} add {url} "
                f"--skill {names} --agent {inventory['agent']} --copy --yes",
                "```",
                "",
            ])
    lines.extend([
        "## Runtime prerequisites and updates",
        "",
        "Diagram authoring/rendering has its own Python packages and renderer",
        "requirements; read the installed diagram skill before installing them.",
        "Keep its source/asset terms with the installed files. XML validity does",
        "not prove a diagram was rendered or independently reviewed.",
        "",
        "Impeccable may download its engine binary on first use. Review that",
        "upstream behavior and your network policy before invoking it. Copying",
        "the skill does not require enabling its optional hooks or live mode.",
        "",
        "Pricing may require public retail APIs or separately authorized commercial",
        "tools. Record attempted sources and concrete blockers; do not invent costs.",
        "Azure operations require separate access and authorization.",
        "",
        "Plugin updates do not update these copies. Maintainers review source",
        "revisions and regenerate these commands; participants review changes",
        "before reinstalling. Preserve local customizations and inspect the diff.",
        "",
    ])
    return "\n".join(lines)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    content = render(json.loads(INVENTORY.read_text()))
    if args.check:
        if not OUTPUT.exists() or OUTPUT.read_text() != content:
            parser.exit(1, "Supporting-skill instructions are stale; run make skills-docs.\n")
    else:
        OUTPUT.write_text(content)


if __name__ == "__main__":
    main()
